PRINT N'--- db/procs/fn_requester_rights.sql';
EXEC (N'/* =====================================================================
   app.fn_requester_rights      APP-3 helper (used by app.usp_request_create)
   Single statement per file; CREATE OR ALTER, safe to run again.

   Input : a person''s e-mail.
   Output: exactly one row
     is_registered        1 = an active row in app.principal_identity (an admin linked the
                          person''s sign-in id to this e-mail, FINAL PLAN/01 section 6.8)
     can_submit_requests  1 = registered and some role the person holds has can_submit_requests
     can_manage_admin     1 = registered and some role the person holds has can_manage_admin

   Roles a person holds: assigned to the person (USER), assigned to a group the person is an
   active member of (GROUP), and, for every registered person, GeneralViewer ("All OXY Users"
   [REF-46:L0204]), the same reading as app.usp_principal_profile. An inactive role or
   assignment never counts. Scope is not needed here: it matters for approving, not submitting
   (see app.fn_stage_eligibility).
   ===================================================================== */
CREATE OR ALTER FUNCTION app.fn_requester_rights
(
    @user_email nvarchar(256)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        CAST(g.reg AS bit) AS is_registered,
        CAST(CASE WHEN g.reg = 1 AND h.submit = 1 THEN 1 ELSE 0 END AS bit) AS can_submit_requests,
        CAST(CASE WHEN g.reg = 1 AND h.adm = 1 THEN 1 ELSE 0 END AS bit)    AS can_manage_admin
    FROM (SELECT LOWER(LTRIM(RTRIM(@user_email))) AS e) AS x
    CROSS APPLY
    (
        SELECT CASE WHEN EXISTS (SELECT 1 FROM app.principal_identity AS i
                                 WHERE i.user_email = x.e AND i.is_active = 1) THEN 1 ELSE 0 END AS reg
    ) AS g
    CROSS APPLY
    (
        SELECT ISNULL(MAX(CAST(ro.can_submit_requests AS int)), 0) AS submit,
               ISNULL(MAX(CAST(ro.can_manage_admin AS int)), 0)    AS adm
        FROM app.role AS ro
        WHERE ro.is_active = 1
          AND (   (g.reg = 1 AND ro.role_name = N''GeneralViewer'')
               OR EXISTS (SELECT 1
                          FROM app.principal_role_assignment AS a
                          WHERE a.is_active = 1
                            AND a.role_name = ro.role_name
                            AND (   (a.principal_type = N''USER'' AND a.principal_key = x.e)
                                 OR (a.principal_type = N''GROUP''
                                     AND EXISTS (SELECT 1 FROM app.group_membership AS m
                                                 WHERE m.is_active = 1 AND m.user_email = x.e AND m.group_key = a.principal_key)))))
    ) AS h
);
');

PRINT N'--- db/procs/fn_stage_eligibility.sql';
EXEC (N'/* =====================================================================
   app.fn_stage_eligibility     APP-3 helper (used by the request procedures and
                                app.fn_request_checks, so the rule lives in ONE place)
   Single statement per file; CREATE OR ALTER, safe to run again.

   FINAL PLAN/01 section 3, "Approval eligibility": a person may decide a request at a stage
   when ALL of these hold:
     1. the stage''s flag is on in a role the person holds (can_responsible_approve for the
        RESPONSIBLE stage, can_accountable_approve for the ACCOUNTABLE stage), and
     2. the scope of that same role assignment covers the request''s profit centre (ALL_ORCM, or
        a list that contains it), and
     3. the person is an active member of the group the request was routed to for that stage.

   Input : the person''s e-mail, the stage (RESPONSIBLE or ACCOUNTABLE), the routed group''s key
           and the request''s profit centre.
   Output: exactly one row
     is_group_member     3. (the group must also be active)
     has_flag_in_scope   1. and 2. together, on the same role assignment
     is_eligible         both

   A role is held when it is assigned to the person (USER) or to a group the person is an active
   member of (GROUP). An unknown stage, a missing group or a blank e-mail gives 0, never an error.
   Segregation of duties (one person may not approve both stages) is a different rule and is
   checked where it is used (app.usp_request_decide, setting SAME_PERSON_BOTH_STAGES).
   ===================================================================== */
CREATE OR ALTER FUNCTION app.fn_stage_eligibility
(
    @user_email         nvarchar(256),
    @stage              nvarchar(12),
    @group_key          nvarchar(64),
    @profit_center_name nvarchar(40)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        CAST(z.mem  AS bit) AS is_group_member,
        CAST(z.flag AS bit) AS has_flag_in_scope,
        CAST(CASE WHEN z.mem = 1 AND z.flag = 1 THEN 1 ELSE 0 END AS bit) AS is_eligible
    FROM (SELECT LOWER(LTRIM(RTRIM(@user_email))) AS e) AS q
    CROSS APPLY
    (
        SELECT
            CASE WHEN EXISTS (SELECT 1
                              FROM app.group_membership AS m
                              JOIN app.security_group AS sg ON sg.group_key = m.group_key AND sg.is_active = 1
                              WHERE m.is_active = 1 AND m.group_key = @group_key AND m.user_email = q.e) THEN 1 ELSE 0 END AS mem,
            CASE WHEN EXISTS (SELECT 1
                              FROM app.principal_role_assignment AS a
                              JOIN app.role AS ro ON ro.role_name = a.role_name AND ro.is_active = 1
                              WHERE a.is_active = 1
                                AND (CASE WHEN @stage = N''RESPONSIBLE'' THEN ro.can_responsible_approve
                                          WHEN @stage = N''ACCOUNTABLE'' THEN ro.can_accountable_approve
                                          ELSE 0 END) = 1
                                AND (   (a.principal_type = N''USER'' AND a.principal_key = q.e)
                                     OR (a.principal_type = N''GROUP''
                                         AND EXISTS (SELECT 1 FROM app.group_membership AS m2
                                                     WHERE m2.is_active = 1 AND m2.user_email = q.e AND m2.group_key = a.principal_key)))
                                AND (   a.scope_type = N''ALL_ORCM''
                                     OR EXISTS (SELECT 1 FROM app.principal_role_assignment_scope AS s
                                                WHERE s.assignment_id = a.assignment_id AND s.profit_center_name = @profit_center_name))) THEN 1 ELSE 0 END AS flag
    ) AS z
);
');

PRINT N'--- db/procs/fn_value_check.sql';
EXEC (N'/* =====================================================================
   app.fn_value_check           APP-3 helper (used by app.usp_request_create, usp_request_resubmit
                                and the VALUE_ALLOWED approval check, so the rule lives in ONE place)
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs gold.vw_floc_current (the synthetic stub or the data engineer''s view).

   Is a proposed value acceptable for a catalogue field? FINAL PLAN/01 section 6.3 ("validates the
   field and value against the catalogue and allowed values") and section 6.2 (D-18).

   Input : the field code and the proposed value.
   Output: exactly one row with `problem`: NULL when the value is acceptable, otherwise a plain-English
           reason (at most 400 characters). The reasons, in the order they are tried:
     - the field is not in the catalogue
     - no value (blank after trimming outer spaces)
     - longer than the catalogue''s max_length (the SAP field length)
     - a DECIMAL field that is not a plain number: digits and at most one decimal point, no sign,
       no thousands separator, at most 4 decimals (gold keeps decimal(18,4))
     - allowed_values_source LIST and the value is not an active entry of app.field_allowed_value
       (exact match, letter case included: the codes go to SAP as typed)
     - allowed_values_source CLASS_CHARACTERISTIC: refused for now, no field uses it yet and the
       table gold.class_characteristic arrives with the data engineer (DE-3)
     - FUNCTIONAL_LOCATION: the new location must exist in gold.vw_floc_current (decision D-18; the
       open point for DE-3 is that this view must hold every FLOC a heater could move to)

   Does NOT check that the value differs from the old one, that the field is editable, or who is
   asking: those depend on the request and are checked by the procedures.
   ===================================================================== */
CREATE OR ALTER FUNCTION app.fn_value_check
(
    @field_code nvarchar(64),
    @new_value  nvarchar(400)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        CAST(
            CASE
                WHEN c.field_code IS NULL
                    THEN N''the field is not in the catalogue''
                WHEN v.val IS NULL OR v.val = N''''
                    THEN N''a new value is required''
                WHEN c.max_length IS NOT NULL AND LEN(v.val) > c.max_length
                    THEN N''the value is longer than '' + CAST(c.max_length AS nvarchar(10)) + N'' characters, the length of the SAP field''
                WHEN c.data_type = N''DECIMAL''
                     AND (   v.val LIKE N''%[^0-9.]%''
                          OR v.val NOT LIKE N''%[0-9]%''
                          OR v.val LIKE N''%.%.%''
                          OR v.val LIKE N''%.[0-9][0-9][0-9][0-9][0-9]%'')
                    THEN N''the value must be a number: digits and one decimal point, at most 4 decimals''
                WHEN c.allowed_values_source = N''LIST''
                     AND NOT EXISTS (SELECT 1
                                     FROM app.field_allowed_value AS a
                                     WHERE a.field_code = c.field_code
                                       AND a.is_active = 1
                                       AND a.allowed_value COLLATE Latin1_General_BIN2 = v.val COLLATE Latin1_General_BIN2)
                    THEN N''the value is not in the allowed list for this field''
                WHEN c.allowed_values_source = N''CLASS_CHARACTERISTIC''
                    THEN N''allowed values from the class characteristics are not available yet (data engineer, DE-3)''
                WHEN c.field_code = N''FUNCTIONAL_LOCATION''
                     AND NOT EXISTS (SELECT 1
                                     FROM gold.vw_floc_current AS f
                                     WHERE f.functional_location COLLATE Latin1_General_BIN2 = v.val COLLATE Latin1_General_BIN2)
                    THEN N''that functional location does not exist''
                ELSE NULL
            END AS nvarchar(400)) AS problem
    FROM (SELECT LTRIM(RTRIM(@new_value)) AS val) AS v
    LEFT JOIN app.field_catalog AS c ON c.field_code = @field_code
);
');

PRINT N'--- db/procs/fn_request_checks.sql';
EXEC (N'/* =====================================================================
   app.fn_request_checks        APP-3; FINAL PLAN/03 APP-3 step 2, REF-52 [L0189-L0190]
                                (used by app.usp_request_checks and app.usp_request_decide)
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs the gold views (the synthetic stub or the data engineer''s): gold.vw_equipment_current,
   gold.vw_equipment_field_current, gold.vw_floc_current; and app.fn_stage_eligibility,
   app.fn_value_check.

   The approval checks of one request, live, as the approver would see them. Six rows, always in
   this order, each with PASS, FAIL or NOT_CHECKED, a plain-English message and the time:

     1 ASSOCIATION_MATCH            the heater is still at the functional location (FLOC) the request
                                    was raised at (for a FLOC request: the FLOC still exists)
     2 OLD_VALUE_CURRENT            the golden value is still the value the requester saw (numbers
                                    compare as numbers, text compares exactly, blank equals blank)
     3 VALUE_ALLOWED                the proposed value is still acceptable (app.fn_value_check)
     4 UNITS_EXPLICIT               a numeric field must carry its unit in the catalogue [INFERRED
                                    reading of "units explicit"]
     5 NO_CONFLICTING_OPEN_REQUEST  no other open request proposes a different value for the same field
                                    of the same heater (or FLOC)
     6 USER_ELIGIBLE_FOR_STAGE      the person named in @actor_email may decide this stage: flag, scope
                                    and group (app.fn_stage_eligibility), and, at the accountable stage
                                    with SAME_PERSON_BOTH_STAGES = 0, did not approve the first stage

   A request that is not waiting for a decision (status other than PENDING_RESPONSIBLE or
   PENDING_ACCOUNTABLE) gets NOT_CHECKED on every row: the checks mean something only while a person
   is about to decide, and a merged request would otherwise "fail" check 2 because the value changed.
   A blank @actor_email gives NOT_CHECKED on row 6 (the detail screen can show checks without a user).
   An unknown request id returns no rows.

   Input : @request_id, @actor_email (the person who is about to decide; may be NULL)
   Output: request_id, request_status, check_order, check_code, check_status, message, checked_at_utc

   The approval procedure blocks only on FAIL of rows 1 to 5 (row 6 it enforces itself, with its own
   refusal). NOT_CHECKED never blocks.
   ===================================================================== */
CREATE OR ALTER FUNCTION app.fn_request_checks
(
    @request_id  bigint,
    @actor_email nvarchar(256)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        r.request_id,
        r.request_status,
        c.check_order,
        CAST(c.check_code   AS nvarchar(40))  AS check_code,
        CAST(c.check_status AS nvarchar(12))  AS check_status,
        CAST(c.message      AS nvarchar(400)) AS message,
        SYSUTCDATETIME() AS checked_at_utc
    FROM app.change_request AS r
    LEFT JOIN app.field_catalog AS fc ON fc.field_code = r.field_code
    OUTER APPLY (SELECT TOP (1) 1 AS ok, e.functional_location AS floc
                 FROM gold.vw_equipment_current AS e
                 WHERE r.entity_type = N''EQUIPMENT'' AND e.equipment_id = r.equipment_id) AS ge
    OUTER APPLY (SELECT TOP (1) f.current_value AS val
                 FROM gold.vw_equipment_field_current AS f
                 WHERE r.entity_type = N''EQUIPMENT'' AND f.equipment_id = r.equipment_id AND f.field_code = r.field_code) AS gv
    OUTER APPLY (SELECT TOP (1) 1 AS ok, l.floc_class AS floc_class
                 FROM gold.vw_floc_current AS l
                 WHERE r.entity_type = N''FLOC'' AND l.functional_location = r.functional_location) AS gl
    CROSS APPLY (SELECT CASE r.request_status WHEN N''PENDING_RESPONSIBLE'' THEN N''RESPONSIBLE''
                                              WHEN N''PENDING_ACCOUNTABLE'' THEN N''ACCOUNTABLE''
                                              ELSE NULL END AS stage) AS st
    CROSS APPLY (SELECT CASE st.stage WHEN N''RESPONSIBLE'' THEN r.responsible_group
                                      WHEN N''ACCOUNTABLE'' THEN r.accountable_group
                                      ELSE NULL END AS grp) AS sg
    CROSS APPLY (SELECT LOWER(LTRIM(RTRIM(@actor_email))) AS a) AS ac
    CROSS APPLY (SELECT CASE WHEN r.entity_type = N''EQUIPMENT'' OR r.field_code = N''FLOC_CLASS'' THEN 1 ELSE 0 END AS supported,
                         CASE WHEN r.entity_type = N''EQUIPMENT'' THEN ge.ok ELSE gl.ok END AS known,
                         CASE WHEN r.entity_type = N''EQUIPMENT'' THEN gv.val ELSE gl.floc_class END AS cur) AS k
    CROSS APPLY (SELECT ISNULL(LTRIM(RTRIM(r.old_value)), N'''') AS oldv,
                         ISNULL(LTRIM(RTRIM(k.cur)), N'''')       AS curv,
                         ISNULL(LTRIM(RTRIM(r.new_value)), N'''') AS newv) AS t
    CROSS APPLY (SELECT CASE WHEN t.oldv COLLATE Latin1_General_BIN2 = t.curv COLLATE Latin1_General_BIN2 THEN 1
                             WHEN fc.data_type = N''DECIMAL''
                                  AND TRY_CONVERT(decimal(18,4), NULLIF(t.oldv, N'''')) = TRY_CONVERT(decimal(18,4), NULLIF(t.curv, N'''')) THEN 1
                             ELSE 0 END AS eq) AS q
    OUTER APPLY app.fn_value_check(r.field_code, r.new_value) AS vc
    OUTER APPLY (SELECT TOP (1) o.request_ref AS ref
                 FROM app.change_request AS o
                 WHERE o.request_id <> r.request_id
                   AND o.request_status <> N''APPROVED'' AND o.request_status <> N''REJECTED'' AND o.request_status <> N''CANCELLED''
                   AND o.field_code = r.field_code
                   AND (   (r.entity_type = N''EQUIPMENT'' AND o.equipment_id = r.equipment_id)
                        OR (r.entity_type = N''FLOC'' AND o.entity_type = N''FLOC'' AND o.functional_location = r.functional_location))
                   AND ISNULL(o.new_value, N'''') COLLATE Latin1_General_BIN2 <> t.newv COLLATE Latin1_General_BIN2
                 ORDER BY o.request_id) AS cf
    OUTER APPLY (SELECT TOP (1) s.setting_value AS v
                 FROM app.app_setting AS s
                 WHERE s.setting_key = N''SAME_PERSON_BOTH_STAGES'') AS sp
    OUTER APPLY app.fn_stage_eligibility(ac.a, st.stage, sg.grp, r.profit_center_name) AS el
    CROSS APPLY (SELECT CASE WHEN st.stage = N''ACCOUNTABLE''
                              AND ISNULL(sp.v, N''0'') = N''0''
                              AND EXISTS (SELECT 1 FROM app.change_request_event AS ev
                                          WHERE ev.request_id = r.request_id
                                            AND ev.event_type = N''RESPONSIBLE_APPROVED''
                                            AND ev.actor = ac.a) THEN 1 ELSE 0 END AS blocked) AS sgr
    CROSS APPLY
    (
        SELECT
            N''the request is '' + r.request_status + N'': checks apply only while it waits for a decision'' AS notpending,

            -- 1 ASSOCIATION_MATCH
            CASE WHEN st.stage IS NULL THEN N''NOT_CHECKED''
                 WHEN r.entity_type = N''EQUIPMENT'' AND ge.ok IS NULL THEN N''FAIL''
                 WHEN r.entity_type = N''EQUIPMENT'' AND r.functional_location IS NULL THEN N''NOT_CHECKED''
                 WHEN r.entity_type = N''EQUIPMENT''
                      AND ISNULL(ge.floc, N'''') COLLATE Latin1_General_BIN2 = r.functional_location COLLATE Latin1_General_BIN2 THEN N''PASS''
                 WHEN r.entity_type = N''EQUIPMENT'' THEN N''FAIL''
                 WHEN r.entity_type = N''FLOC'' AND gl.ok IS NULL THEN N''FAIL''
                 WHEN r.entity_type = N''FLOC'' THEN N''PASS''
                 ELSE N''NOT_CHECKED'' END AS c1s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN r.entity_type = N''EQUIPMENT'' AND ge.ok IS NULL THEN N''the heater is no longer in gold''
                 WHEN r.entity_type = N''EQUIPMENT'' AND r.functional_location IS NULL THEN N''no location was stored with the request''
                 WHEN r.entity_type = N''EQUIPMENT''
                      AND ISNULL(ge.floc, N'''') COLLATE Latin1_General_BIN2 = r.functional_location COLLATE Latin1_General_BIN2
                      THEN N''the heater is still at the location the request was raised at''
                 WHEN r.entity_type = N''EQUIPMENT''
                      THEN N''the heater is now at '' + LEFT(ISNULL(ge.floc, N''(none)''), 60) + N'', the request was raised at '' + LEFT(r.functional_location, 60)
                 WHEN r.entity_type = N''FLOC'' AND gl.ok IS NULL THEN N''the functional location is no longer in gold''
                 WHEN r.entity_type = N''FLOC'' THEN N''the functional location still exists''
                 ELSE N''not applicable'' END AS c1m,

            -- 2 OLD_VALUE_CURRENT
            CASE WHEN st.stage IS NULL THEN N''NOT_CHECKED''
                 WHEN k.supported = 0 THEN N''NOT_CHECKED''
                 WHEN k.known IS NULL THEN N''FAIL''
                 WHEN q.eq = 1 THEN N''PASS''
                 ELSE N''FAIL'' END AS c2s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN k.supported = 0 THEN N''the current value of this field is not read from gold yet''
                 WHEN k.known IS NULL THEN N''the heater or location is no longer in gold''
                 WHEN q.eq = 1 THEN N''the current value is still the one the request expected''
                 ELSE N''the current value is "'' + LEFT(t.curv, 100) + N''", the request expected "'' + LEFT(t.oldv, 100) + N''"'' END AS c2m,

            -- 3 VALUE_ALLOWED
            CASE WHEN st.stage IS NULL OR r.field_code IS NULL THEN N''NOT_CHECKED''
                 WHEN vc.problem IS NULL THEN N''PASS''
                 ELSE N''FAIL'' END AS c3s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN r.field_code IS NULL THEN N''no catalogue field to check against''
                 WHEN vc.problem IS NULL THEN N''the proposed value is allowed''
                 ELSE vc.problem END AS c3m,

            -- 4 UNITS_EXPLICIT
            CASE WHEN st.stage IS NULL OR r.field_code IS NULL THEN N''NOT_CHECKED''
                 WHEN fc.data_type = N''DECIMAL'' AND fc.unit IS NULL THEN N''FAIL''
                 ELSE N''PASS'' END AS c4s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN r.field_code IS NULL THEN N''no catalogue field to check against''
                 WHEN fc.data_type = N''DECIMAL'' AND fc.unit IS NULL THEN N''this numeric field has no unit in the catalogue, so the unit is not explicit''
                 WHEN fc.data_type = N''DECIMAL'' THEN N''the unit is '' + fc.unit + N'', from the catalogue''
                 ELSE N''no unit applies to this field'' END AS c4m,

            -- 5 NO_CONFLICTING_OPEN_REQUEST
            CASE WHEN st.stage IS NULL OR r.field_code IS NULL THEN N''NOT_CHECKED''
                 WHEN cf.ref IS NOT NULL THEN N''FAIL''
                 ELSE N''PASS'' END AS c5s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN r.field_code IS NULL THEN N''no catalogue field to check against''
                 WHEN cf.ref IS NOT NULL THEN N''request '' + cf.ref + N'' is also open on this field with a different value''
                 ELSE N''no other open request proposes a different value'' END AS c5m,

            -- 6 USER_ELIGIBLE_FOR_STAGE
            CASE WHEN st.stage IS NULL THEN N''NOT_CHECKED''
                 WHEN ac.a IS NULL OR ac.a = N'''' THEN N''NOT_CHECKED''
                 WHEN el.is_group_member = 0 OR el.has_flag_in_scope = 0 THEN N''FAIL''
                 WHEN sgr.blocked = 1 THEN N''FAIL''
                 ELSE N''PASS'' END AS c6s,
            CASE WHEN st.stage IS NULL THEN NULL
                 WHEN ac.a IS NULL OR ac.a = N'''' THEN N''no approver was named, so eligibility was not checked''
                 WHEN el.is_group_member = 0 THEN N''not an active member of the group for this stage ('' + ISNULL(sg.grp, N''none'') + N'')''
                 WHEN el.has_flag_in_scope = 0 THEN N''no role of this person allows the '' + st.stage + N'' stage for '' + LEFT(r.profit_center_name, 40)
                 WHEN sgr.blocked = 1 THEN N''the same person may not approve both stages of one request (setting SAME_PERSON_BOTH_STAGES)''
                 ELSE N''allowed to decide the '' + st.stage + N'' stage'' END AS c6m
    ) AS x
    CROSS APPLY (VALUES
        (1, N''ASSOCIATION_MATCH'',           x.c1s, ISNULL(x.c1m, x.notpending)),
        (2, N''OLD_VALUE_CURRENT'',           x.c2s, ISNULL(x.c2m, x.notpending)),
        (3, N''VALUE_ALLOWED'',               x.c3s, ISNULL(x.c3m, x.notpending)),
        (4, N''UNITS_EXPLICIT'',              x.c4s, ISNULL(x.c4m, x.notpending)),
        (5, N''NO_CONFLICTING_OPEN_REQUEST'', x.c5s, ISNULL(x.c5m, x.notpending)),
        (6, N''USER_ELIGIBLE_FOR_STAGE'',     x.c6s, ISNULL(x.c6m, x.notpending))
    ) AS c (check_order, check_code, check_status, message)
    WHERE r.request_id = @request_id
);
');

PRINT N'--- db/procs/usp_notification_enqueue.sql';
EXEC (N'/* =====================================================================
   app.usp_notification_enqueue   APP-3, INTERNAL (called only by the request procedures;
                                  no function exposes it). FINAL PLAN/03 section 2.3.
   Single statement per file; CREATE OR ALTER, safe to run again.

   Queues one in-app notification for each recipient: one person (@recipient_email), the active
   members of one group (@recipient_group), or both (a person who is also in the group gets ONE
   message). Writes app.notification only; returns no result set (so a caller can use it freely).

   Nobody gets the same message twice: the unique dedup_key is a SHA-256 over topic, request,
   @event_key and recipient (REF-52 analysis section 4.6, "deduplicate recipients per notification").
   Running the same call again therefore adds nothing. Pass an @event_key that is unique to the
   event (for example ''E'' + the event id), so a later event of the same kind is a new message.

   Never queued: a system address (system:...), an address without an @, or a member of an inactive
   group. An unknown or empty group (for example UNROUTED) queues nothing and is not an error.
   email_status keeps its default NOT_REQUIRED: e-mail is only built if spike S6 passes (APP-8).
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_notification_enqueue
    @topic           nvarchar(30),
    @request_id      bigint,
    @event_key       nvarchar(60),
    @title           nvarchar(200),
    @body            nvarchar(1000),
    @recipient_email nvarchar(256) = NULL,
    @recipient_group nvarchar(64)  = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @r TABLE (email nvarchar(256) NOT NULL PRIMARY KEY);
    DECLARE @one nvarchar(256) = LOWER(LTRIM(RTRIM(@recipient_email)));

    IF @one IS NOT NULL AND CHARINDEX(N''@'', @one) > 1 AND LEFT(@one, 7) <> N''system:''
        INSERT INTO @r (email) VALUES (@one);

    IF @recipient_group IS NOT NULL
        INSERT INTO @r (email)
        SELECT m.user_email
        FROM app.group_membership AS m
        JOIN app.security_group AS g ON g.group_key = m.group_key AND g.is_active = 1
        WHERE m.group_key = @recipient_group
          AND m.is_active = 1
          AND CHARINDEX(N''@'', m.user_email) > 1
          AND LEFT(m.user_email, 7) <> N''system:''
          AND NOT EXISTS (SELECT 1 FROM @r AS x WHERE x.email = m.user_email);

    INSERT INTO app.notification (recipient_email, topic, request_id, title, body, dedup_key)
    SELECT r.email, @topic, @request_id, LEFT(@title, 200), LEFT(@body, 1000), k.dedup_key
    FROM @r AS r
    CROSS APPLY (SELECT CONVERT(char(64), HASHBYTES(''SHA2_256'', CONCAT(@topic, N''|'', @request_id, N''|'', @event_key, N''|'', r.email)), 2) AS dedup_key) AS k
    WHERE NOT EXISTS (SELECT 1 FROM app.notification AS n WHERE n.dedup_key = k.dedup_key);
END
');

PRINT N'--- db/procs/usp_request_create.sql';
EXEC (N'/* =====================================================================
   app.usp_request_create       APP-3; contract FINAL PLAN/01 section 6.3 ("the only door into the
                                workflow"); FINAL PLAN/03 APP-3 step 1; tests: db/tests/t_request_lifecycle.sql
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: the gold views (stub or the data engineer''s), app.usp_route_resolve, app.fn_value_check,
   app.fn_requester_rights, app.usp_notification_enqueue, setting ADMIN_ONLY_FIELDS (seed 0109).

   Every source (field user, desktop user, rule run, data-engineer import) creates a request here.

   What it does, in order (a refusal is a THROW, nothing is written):
     1  checks who and what: source type and requester agree (a person for FIELD / MANUAL; system:...
        for BUSINESS_RULE / CORRECTION_IMPORT); a person must be registered and may submit requests;
        a rule request names its rule and version
     2  checks the field: in the catalogue, active, editable, belongs to the entity type; the four
        admin-only classification fields (setting ADMIN_ONLY_FIELDS) need can_manage_admin from a person
     3  finds the target in gold: the heater (EQUIPMENT) or the functional location (FLOC), and copies
        the facts the routing and the approval checks need (profit centre, class, FLOC, golden version)
     4  checks the value: it differs from the old one, and app.fn_value_check accepts it (length,
        number format, allowed list, a new FLOC must exist, D-18)
     5  suppresses or blocks (no error, an outcome):
          DUPLICATE_SUPPRESSED  an open request with the same de-duplication key exists; for a RULE source
                                also when the latest request with that key was REJECTED or CANCELLED
                                (REF-52 [L0187]: "after rejection/cancellation unless explicitly
                                resubmitted"; a person raising it again counts as explicit)
          BLOCKED_INCOMPATIBLE  another open request proposes a different value for the same field of the
                                same heater (or FLOC)
        Both return the OTHER request''s id and reference.
     6  routes it (app.usp_route_resolve: field > class > wildcard); a rule''s own responsible /
        accountable group, when set, overrides the route''s groups
     7  in ONE transaction: inserts the request as PENDING_RESPONSIBLE, writes the CREATED event with the
        evidence snapshot (+ golden version and baseline watermark), queues the notification to the
        responsible group. A concurrent twin (unique index) is reported as DUPLICATE_SUPPRESSED.

   De-duplication key: SHA-256 (upper-case hex, char(64)) over rule id (empty for non-rule sources),
   entity type, entity key (equipment number, or the FLOC), field code, old value, new value, joined by
   character 31. Run id and rule version are left out on purpose, so a new rule version does not
   duplicate an open request (01 section 6.3, 09 section 4.1).

   Class used for routing: the heater''s equip_class (EQUIPMENT) or the FLOC''s floc_class (FLOC).

   Results: ONE row (request_id, request_ref, outcome, responsible_group, accountable_group) when
   @emit_result = 1 (the default), and always the five @o_ OUTPUT parameters. A caller that creates many
   requests in a loop (the rule engine) passes @emit_result = 0. Do not call this procedure from
   INSERT ... EXEC: it uses INSERT ... EXEC itself (SQL Server does not allow nesting); read the OUTPUT
   parameters instead.

   Refusal numbers (THROW): 50101 unknown source, 50102 source not available here, 50103 unknown entity
   type, 50104 requester missing or not an e-mail, 50105 source and requester do not agree, 50106 a rule
   request without its rule, 50107 not registered or may not submit, 50108 unknown rule version,
   50110 unknown field, 50111 field inactive or not editable, 50112 field belongs to another entity type,
   50113 field is admin-only, 50114 no heater / location named, 50115 not found in gold, 50116 no profit
   centre, 50120 new value equals the old, 50121 value not acceptable, 50122 evidence is not JSON,
   50123 no reason.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_create
    @source_type         nvarchar(20),
    @entity_type         nvarchar(10),
    @field_code          nvarchar(64),
    @new_value           nvarchar(400),
    @reason              nvarchar(400),
    @requested_by        nvarchar(256),
    @equipment_id        int            = NULL,
    @functional_location nvarchar(40)   = NULL,
    @old_value           nvarchar(400)  = NULL,
    @note                nvarchar(200)  = NULL,
    @source_rule_id      nvarchar(64)   = NULL,
    @source_rule_version int            = NULL,
    @source_result_id    bigint         = NULL,
    @comment             nvarchar(1000) = NULL,
    @evidence_json       nvarchar(4000) = NULL,
    @emit_result         bit            = 1,
    @o_request_id        bigint         = NULL OUTPUT,
    @o_request_ref       nvarchar(12)   = NULL OUTPUT,
    @o_outcome           nvarchar(24)   = NULL OUTPUT,
    @o_responsible_group nvarchar(64)   = NULL OUTPUT,
    @o_accountable_group nvarchar(64)   = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @msg nvarchar(2048);
    DECLARE @by nvarchar(256) = LOWER(LTRIM(RTRIM(@requested_by)));
    DECLARE @is_system bit = CASE WHEN LEFT(@by, 7) = N''system:'' THEN 1 ELSE 0 END;
    DECLARE @newv nvarchar(400) = LTRIM(RTRIM(@new_value));
    DECLARE @oldv nvarchar(400) = NULLIF(LTRIM(RTRIM(@old_value)), N'''');
    DECLARE @floc_in nvarchar(40) = NULLIF(LTRIM(RTRIM(@functional_location)), N'''');
    DECLARE @why nvarchar(400) = LTRIM(RTRIM(@reason));

    /* ---- 1 who and what ---------------------------------------------------------- */
    IF @source_type IS NULL OR @source_type NOT IN (N''BUSINESS_RULE'', N''FIELD'', N''MANUAL'', N''CORRECTION_IMPORT'', N''NEW_CHARACTERISTIC'', N''NEW_RECORD'')
        THROW 50101, N''Unknown request source.'', 1;
    IF @source_type IN (N''NEW_CHARACTERISTIC'', N''NEW_RECORD'')
        THROW 50102, N''This source is not created through usp_request_create (a new field request has its own procedure, APP-9).'', 1;
    IF @entity_type IS NULL OR @entity_type NOT IN (N''EQUIPMENT'', N''FLOC'')
        THROW 50103, N''The entity type must be EQUIPMENT or FLOC.'', 1;
    IF @by IS NULL OR @by = N'''' OR (@is_system = 0 AND CHARINDEX(N''@'', @by) < 2)
        THROW 50104, N''The requester must be a person''''s e-mail address or a system:... name.'', 1;
    IF (@source_type IN (N''BUSINESS_RULE'', N''CORRECTION_IMPORT'') AND @is_system = 0)
       OR (@source_type IN (N''FIELD'', N''MANUAL'') AND @is_system = 1)
        THROW 50105, N''The requester does not fit the source: a person raises FIELD and MANUAL requests; the rule run and the data engineer''''s import (system:...) raise BUSINESS_RULE and CORRECTION_IMPORT requests.'', 1;
    IF @source_type = N''BUSINESS_RULE'' AND (@source_rule_id IS NULL OR @source_rule_version IS NULL)
        THROW 50106, N''A rule request must name its rule and rule version.'', 1;
    IF @source_type = N''BUSINESS_RULE''
       AND NOT EXISTS (SELECT 1 FROM app.business_rules AS br WHERE br.rule_id = @source_rule_id AND br.rule_version = @source_rule_version)
        THROW 50108, N''Unknown rule version.'', 1;
    IF @source_type <> N''BUSINESS_RULE'' AND (@source_rule_id IS NOT NULL OR @source_rule_version IS NOT NULL)
        THROW 50106, N''Only a rule request may name a rule.'', 1;

    DECLARE @reg bit = 1, @can_submit bit = 1, @is_admin bit = 1;
    IF @is_system = 0
    BEGIN
        SELECT @reg = u.is_registered, @can_submit = u.can_submit_requests, @is_admin = u.can_manage_admin
        FROM app.fn_requester_rights(@by) AS u;
        IF @reg = 0 OR @can_submit = 0
            THROW 50107, N''This person is not registered, or may not submit requests.'', 1;
    END

    IF @why IS NULL OR @why = N''''
        THROW 50123, N''A reason is required.'', 1;
    IF @evidence_json IS NOT NULL AND ISJSON(@evidence_json) = 0
        THROW 50122, N''The evidence must be valid JSON.'', 1;

    /* ---- 2 the field -------------------------------------------------------------- */
    DECLARE @f_entity nvarchar(10), @f_editable bit, @f_active bit, @f_type nvarchar(10), @f_label nvarchar(100);
    SELECT @f_entity = c.entity_type, @f_editable = c.is_editable, @f_active = c.is_active, @f_type = c.data_type, @f_label = c.label
    FROM app.field_catalog AS c
    WHERE c.field_code = @field_code;
    IF @f_entity IS NULL
        THROW 50110, N''That field is not in the catalogue.'', 1;
    IF @f_active = 0 OR @f_editable = 0
        THROW 50111, N''That field is switched off or cannot be changed by a request.'', 1;
    IF @f_entity <> @entity_type
        THROW 50112, N''That field belongs to the other entity type (heater or location).'', 1;

    DECLARE @admin_only nvarchar(400) = ISNULL((SELECT s.setting_value FROM app.app_setting AS s WHERE s.setting_key = N''ADMIN_ONLY_FIELDS''), N'''');
    IF @is_system = 0 AND @is_admin = 0
       AND EXISTS (SELECT 1 FROM STRING_SPLIT(@admin_only, N'','') AS a WHERE LTRIM(RTRIM(a.value)) = @field_code)
        THROW 50113, N''Only an admin may ask to change this field by hand (a rule or the data engineer''''s import may propose it).'', 1;

    /* ---- 3 the target in gold ----------------------------------------------------- */
    DECLARE @eqnum nvarchar(18), @floc nvarchar(40), @pc nvarchar(40), @class nvarchar(30);
    DECLARE @golden int, @baseline datetime2(3), @entity_key nvarchar(40);
    IF @entity_type = N''EQUIPMENT''
    BEGIN
        IF @equipment_id IS NULL
            THROW 50114, N''Name the heater (equipment_id).'', 1;
        SELECT @eqnum = e.equipment_number, @floc = e.functional_location, @pc = e.profit_center_name,
               @class = e.equip_class, @golden = e.golden_version_id, @baseline = e.baseline_as_of_utc
        FROM gold.vw_equipment_current AS e
        WHERE e.equipment_id = @equipment_id;
        IF @@ROWCOUNT = 0
            THROW 50115, N''That heater is not in gold.'', 1;
        SET @entity_key = @eqnum;
    END
    ELSE
    BEGIN
        IF @floc_in IS NULL
            THROW 50114, N''Name the functional location.'', 1;
        SELECT @floc = f.functional_location, @pc = f.profit_center_name, @class = f.floc_class, @golden = f.golden_version_id
        FROM gold.vw_floc_current AS f
        WHERE f.functional_location = @floc_in;
        IF @@ROWCOUNT = 0
            THROW 50115, N''That functional location is not in gold.'', 1;
        SET @equipment_id = NULL;
        SET @entity_key = @floc;
    END
    IF @pc IS NULL OR @pc = N''''
        THROW 50116, N''The heater or location has no profit centre, so the request cannot be routed.'', 1;

    /* ---- 4 the value --------------------------------------------------------------- */
    DECLARE @same bit = 0;
    IF @f_type = N''DECIMAL'' AND TRY_CONVERT(decimal(18,4), @newv) IS NOT NULL AND TRY_CONVERT(decimal(18,4), @oldv) IS NOT NULL
        SET @same = CASE WHEN TRY_CONVERT(decimal(18,4), @newv) = TRY_CONVERT(decimal(18,4), @oldv) THEN 1 ELSE 0 END;
    ELSE
        SET @same = CASE WHEN ISNULL(@oldv, N'''') COLLATE Latin1_General_BIN2 = ISNULL(@newv, N'''') COLLATE Latin1_General_BIN2 THEN 1 ELSE 0 END;

    DECLARE @problem nvarchar(400) = (SELECT v.problem FROM app.fn_value_check(@field_code, @newv) AS v);
    IF @problem IS NOT NULL
    BEGIN
        SET @msg = N''The new value is not acceptable: '' + @problem + N''.'';
        THROW 50121, @msg, 1;
    END
    IF @same = 1
        THROW 50120, N''The new value is the same as the old value.'', 1;

    /* ---- 5 duplicates and conflicts ------------------------------------------------- */
    DECLARE @key char(64) = CONVERT(char(64), HASHBYTES(''SHA2_256'',
        CONCAT(ISNULL(@source_rule_id, N''''), NCHAR(31), @entity_type, NCHAR(31), @entity_key, NCHAR(31),
               @field_code, NCHAR(31), ISNULL(@oldv, N''''), NCHAR(31), @newv)), 2);

    DECLARE @outcome nvarchar(24) = NULL, @id bigint = NULL, @ref nvarchar(12) = NULL;
    DECLARE @rg nvarchar(64), @ag nvarchar(64), @route_id int, @route_used nvarchar(12);

    SELECT TOP (1) @id = d.request_id, @ref = d.request_ref, @rg = d.responsible_group, @ag = d.accountable_group, @outcome = N''DUPLICATE_SUPPRESSED''
    FROM app.change_request AS d
    WHERE d.deduplication_key = @key
      AND d.request_status <> N''APPROVED'' AND d.request_status <> N''REJECTED'' AND d.request_status <> N''CANCELLED''
    ORDER BY d.request_id;

    IF @outcome IS NULL AND @source_type = N''BUSINESS_RULE''
        SELECT TOP (1) @id = d.request_id, @ref = d.request_ref, @rg = d.responsible_group, @ag = d.accountable_group, @outcome = N''DUPLICATE_SUPPRESSED''
        FROM app.change_request AS d
        WHERE d.deduplication_key = @key
          AND d.request_id = (SELECT MAX(l.request_id) FROM app.change_request AS l WHERE l.deduplication_key = @key)
          AND (d.request_status = N''REJECTED'' OR d.request_status = N''CANCELLED'');

    IF @outcome IS NULL
        SELECT TOP (1) @id = o.request_id, @ref = o.request_ref, @rg = o.responsible_group, @ag = o.accountable_group, @outcome = N''BLOCKED_INCOMPATIBLE''
        FROM app.change_request AS o
        WHERE o.field_code = @field_code
          AND o.request_status <> N''APPROVED'' AND o.request_status <> N''REJECTED'' AND o.request_status <> N''CANCELLED''
          AND (   (@entity_type = N''EQUIPMENT'' AND o.equipment_id = @equipment_id)
               OR (@entity_type = N''FLOC'' AND o.entity_type = N''FLOC'' AND o.functional_location = @floc))
        ORDER BY o.request_id;

    /* ---- 6 and 7 route and write ----------------------------------------------------- */
    IF @outcome IS NULL
    BEGIN
        DECLARE @route TABLE
        (
            route_id int NULL, route_used nvarchar(12) NULL, responsible_role nvarchar(64) NULL,
            responsible_group nvarchar(64) NULL, accountable_role nvarchar(64) NULL, accountable_group nvarchar(64) NULL
        );
        INSERT INTO @route (route_id, route_used, responsible_role, responsible_group, accountable_role, accountable_group)
        EXEC app.usp_route_resolve @entity_type = @entity_type, @request_action = N''UPDATE'', @profit_center_name = @pc,
                                   @field_code = @field_code, @class_code = @class;
        SELECT TOP (1) @route_id = r.route_id, @route_used = r.route_used, @rg = ISNULL(r.responsible_group, N''UNROUTED''), @ag = ISNULL(r.accountable_group, N''UNROUTED'')
        FROM @route AS r;
        SET @rg = ISNULL(@rg, N''UNROUTED'');
        SET @ag = ISNULL(@ag, N''UNROUTED'');

        IF @source_type = N''BUSINESS_RULE''
            SELECT @rg = ISNULL(br.responsible_group, @rg), @ag = ISNULL(br.accountable_group, @ag)
            FROM app.business_rules AS br
            WHERE br.rule_id = @source_rule_id AND br.rule_version = @source_rule_version;

        DECLARE @details nvarchar(max) =
            (SELECT N''CREATED'' AS [event], @source_type AS source_type, @entity_type AS entity_type, @entity_key AS entity_key,
                    @route_used AS route_used, @golden AS golden_version_id, @baseline AS baseline_as_of_utc,
                    JSON_QUERY(@evidence_json) AS evidence
             FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);

        DECLARE @own bit = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;
        DECLARE @errno int;
        BEGIN TRY
            IF @own = 1 BEGIN TRANSACTION;

            INSERT INTO app.change_request
                (entity_type, equipment_id, equipment_number, functional_location, profit_center_name, class_code, request_action,
                 source_type, source_result_id, source_rule_id, source_rule_version, field_code, old_value, new_value, reason, note,
                 requested_by, request_status, responsible_group, accountable_group, route_id, deduplication_key)
            VALUES
                (@entity_type, @equipment_id, @eqnum, @floc, @pc, @class, N''UPDATE'',
                 @source_type, @source_result_id, @source_rule_id, @source_rule_version, @field_code, @oldv, @newv, @why, @note,
                 @by, N''PENDING_RESPONSIBLE'', @rg, @ag, @route_id, @key);
            SET @id = SCOPE_IDENTITY();
            SET @ref = (SELECT c.request_ref FROM app.change_request AS c WHERE c.request_id = @id);

            INSERT INTO app.change_request_event
                (request_id, event_type, approval_stage, actor, actor_group, comments, status_from, status_to, event_details_json)
            VALUES
                (@id, N''CREATED'', NULL, @by, NULL, @comment, NULL, N''PENDING_RESPONSIBLE'', @details);

            DECLARE @title nvarchar(200) = N''Request '' + @ref + N'' needs your approval'';
            DECLARE @body nvarchar(1000) = LEFT(@ref + N'': '' + @f_label + N'' of '' + ISNULL(@entity_key, N'''') + N'' from "'' + ISNULL(@oldv, N''(blank)'')
                                                + N''" to "'' + @newv + N''". Reason: '' + @why, 1000);
            EXEC app.usp_notification_enqueue @topic = N''REQUEST_PENDING_RESPONSIBLE'', @request_id = @id, @event_key = N''CREATED'',
                                              @title = @title, @body = @body, @recipient_group = @rg;

            IF @own = 1 COMMIT TRANSACTION;
            SET @outcome = N''CREATED'';
        END TRY
        BEGIN CATCH
            SET @errno = ERROR_NUMBER();
            IF @own = 1 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
            IF @errno IN (2601, 2627)
            BEGIN
                -- a concurrent twin got in first: report it as the duplicate it is
                SET @id = NULL;
                SELECT TOP (1) @id = d.request_id, @ref = d.request_ref, @rg = d.responsible_group, @ag = d.accountable_group
                FROM app.change_request AS d
                WHERE d.deduplication_key = @key
                  AND d.request_status <> N''APPROVED'' AND d.request_status <> N''REJECTED'' AND d.request_status <> N''CANCELLED''
                ORDER BY d.request_id;
                IF @id IS NULL THROW;
                SET @outcome = N''DUPLICATE_SUPPRESSED'';
            END
            ELSE
                THROW;
        END CATCH;
    END

    SET @o_request_id = @id;
    SET @o_request_ref = @ref;
    SET @o_outcome = @outcome;
    SET @o_responsible_group = @rg;
    SET @o_accountable_group = @ag;

    IF @emit_result = 1
        SELECT @id AS request_id, @ref AS request_ref, @outcome AS outcome, @rg AS responsible_group, @ag AS accountable_group;
END
');

PRINT N'--- db/procs/usp_request_checks.sql';
EXEC (N'/* =====================================================================
   app.usp_request_checks       APP-3; FINAL PLAN/03 APP-3 step 2; called by the function getRequestChecks
   Single statement per file; CREATE OR ALTER, safe to run again. Reads only.

   The live approval checks of one request (PASS / FAIL / NOT_CHECKED with a message and a time),
   exactly as app.usp_request_decide will see them. The rules are in app.fn_request_checks.

   Input : @request_id, and optionally @actor_email, the person who is about to decide (the row
           USER_ELIGIBLE_FOR_STAGE is NOT_CHECKED without one).
   Output: six rows, check_order 1 to 6: request_id, request_status, check_order, check_code,
           check_status, message, checked_at_utc.
   Refusal: 50130 when the request does not exist.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_checks
    @request_id  bigint,
    @actor_email nvarchar(256) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM app.change_request AS r WHERE r.request_id = @request_id)
        THROW 50130, N''That request does not exist.'', 1;

    SELECT c.request_id, c.request_status, c.check_order, c.check_code, c.check_status, c.message, c.checked_at_utc
    FROM app.fn_request_checks(@request_id, @actor_email) AS c
    ORDER BY c.check_order;
END
');

PRINT N'--- db/procs/usp_request_decide.sql';
EXEC (N'/* =====================================================================
   app.usp_request_decide       APP-3; FINAL PLAN/01 section 2.2 (write path), 03 APP-3 step 3;
                                tests: db/tests/t_request_lifecycle.sql
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.fn_stage_eligibility, app.fn_request_checks, app.usp_notification_enqueue.

   One approver decides one request: APPROVE, REJECT or RETURN. All the rules live here (the function
   only identifies the caller). In order; a refusal is a THROW and nothing is written:

     50131 the actor must be a person''s e-mail (never a system:... name)      50132 unknown decision
     50133 no such request                                                     50134 not waiting for a decision
     50135 @expected_status given and the request has moved on (the screen is out of date)
     50136 REJECT and RETURN need a comment
     50141 not an active member of the group the request was routed to for this stage
     50142 no role of the person has the stage''s flag with a scope that covers the profit centre
     50143 segregation: the same person approved the first stage and SAME_PERSON_BOTH_STAGES = 0
           (only for APPROVE at the accountable stage)
     50144 APPROVE blocked by a FAILED approval check (app.fn_request_checks rows 1 to 5; NOT_CHECKED does
           not block; a stale request can still be REJECTED or RETURNED)
     50137 RETURN to someone other than the allowed recipient: the submitter (field / manual requests) or
           the rule''s resolution group (rule requests); a request raised by system:... goes to its
           responsible group (Q-465 working assumption, setting RETURN_RECIPIENT_RULE)
     50149 somebody else changed the request between the read and the write (row_version)

   What it writes, in ONE transaction: the new status, the event (type, stage, actor, group, comment,
   status before and after, the check results as JSON), and the notifications:
     APPROVE at RESPONSIBLE   -> PENDING_ACCOUNTABLE, event RESPONSIBLE_APPROVED, group notified
     APPROVE at ACCOUNTABLE   -> APPROVED, event ACCOUNTABLE_APPROVED, requester notified; needs_merge = 1
     REJECT                   -> REJECTED, event REJECTED, requester notified with the comment
     RETURN                   -> RETURNED, event RETURNED, the recipient notified with the comment
   The merge into gold is NOT done here: it is a separate step after the approval commits (01 section 2.2).
   The function calls gold.usp_apply_approved_change when needs_merge = 1 and records the outcome with
   app.usp_request_record_merge.

   Result: ONE row (request_id, request_ref, decision, previous_status, new_status, stage, needs_merge) when
   @emit_result = 1 (the default), and always @o_new_status and @o_needs_merge. app.usp_request_bulk_decide
   passes @emit_result = 0. Do not call this procedure from INSERT ... EXEC; read the OUTPUT parameters.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_decide
    @request_id            bigint,
    @actor_email           nvarchar(256),
    @decision              nvarchar(10),
    @comment               nvarchar(1000) = NULL,
    @expected_status       nvarchar(24)   = NULL,
    @return_recipient_type nvarchar(10)   = NULL,
    @return_recipient      nvarchar(256)  = NULL,
    @emit_result           bit            = 1,
    @o_new_status          nvarchar(24)   = NULL OUTPUT,
    @o_needs_merge         bit            = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @msg nvarchar(2048);
    DECLARE @actor nvarchar(256) = LOWER(LTRIM(RTRIM(@actor_email)));
    DECLARE @dec nvarchar(10) = UPPER(LTRIM(RTRIM(@decision)));
    DECLARE @cmt nvarchar(1000) = NULLIF(LTRIM(RTRIM(@comment)), N'''');

    IF @actor IS NULL OR CHARINDEX(N''@'', @actor) < 2 OR LEFT(@actor, 7) = N''system:''
        THROW 50131, N''The decision must come from a person (an e-mail address).'', 1;
    IF @dec IS NULL OR @dec NOT IN (N''APPROVE'', N''REJECT'', N''RETURN'')
        THROW 50132, N''The decision must be APPROVE, REJECT or RETURN.'', 1;

    /* ---- the request -------------------------------------------------------------- */
    DECLARE @status nvarchar(24), @rg nvarchar(64), @ag nvarchar(64), @pc nvarchar(40), @source nvarchar(20);
    DECLARE @rule nvarchar(64), @rv int, @by nvarchar(256), @ref nvarchar(12), @rowver binary(8);
    SELECT @status = r.request_status, @rg = r.responsible_group, @ag = r.accountable_group, @pc = r.profit_center_name,
           @source = r.source_type, @rule = r.source_rule_id, @rv = r.source_rule_version, @by = r.requested_by,
           @ref = r.request_ref, @rowver = r.row_version
    FROM app.change_request AS r
    WHERE r.request_id = @request_id;
    IF @status IS NULL
        THROW 50133, N''That request does not exist.'', 1;
    IF @status NOT IN (N''PENDING_RESPONSIBLE'', N''PENDING_ACCOUNTABLE'')
    BEGIN
        SET @msg = N''The request is '' + @status + N''; only a request that waits for a decision can be decided.'';
        THROW 50134, @msg, 1;
    END
    IF @expected_status IS NOT NULL AND @expected_status <> @status
    BEGIN
        SET @msg = N''The request is now '' + @status + N'', not '' + @expected_status + N'': reload it and decide again.'';
        THROW 50135, @msg, 1;
    END

    DECLARE @stage nvarchar(12) = CASE WHEN @status = N''PENDING_RESPONSIBLE'' THEN N''RESPONSIBLE'' ELSE N''ACCOUNTABLE'' END;
    DECLARE @grp nvarchar(64) = CASE WHEN @stage = N''RESPONSIBLE'' THEN @rg ELSE @ag END;

    IF @dec IN (N''REJECT'', N''RETURN'') AND @cmt IS NULL
        THROW 50136, N''A comment is required to reject or return a request.'', 1;

    /* ---- who may decide ---------------------------------------------------------- */
    DECLARE @is_member bit, @has_flag bit;
    SELECT @is_member = e.is_group_member, @has_flag = e.has_flag_in_scope
    FROM app.fn_stage_eligibility(@actor, @stage, @grp, @pc) AS e;
    IF @is_member = 0
    BEGIN
        SET @msg = N''You are not an active member of the group for this stage ('' + ISNULL(@grp, N''none'') + N'').'';
        THROW 50141, @msg, 1;
    END
    IF @has_flag = 0
    BEGIN
        SET @msg = N''No role of yours allows the '' + @stage + N'' stage for '' + ISNULL(@pc, N''this profit centre'') + N''.'';
        THROW 50142, @msg, 1;
    END

    IF @dec = N''APPROVE'' AND @stage = N''ACCOUNTABLE''
       AND ISNULL((SELECT s.setting_value FROM app.app_setting AS s WHERE s.setting_key = N''SAME_PERSON_BOTH_STAGES''), N''0'') = N''0''
       AND EXISTS (SELECT 1 FROM app.change_request_event AS ev
                   WHERE ev.request_id = @request_id AND ev.event_type = N''RESPONSIBLE_APPROVED'' AND ev.actor = @actor)
        THROW 50143, N''The same person may not approve both stages of one request.'', 1;

    /* ---- approval checks (a stale or failing request may still be rejected or returned) -- */
    DECLARE @failed nvarchar(max);
    IF @dec = N''APPROVE''
    BEGIN
        SELECT @failed = STRING_AGG(CAST(c.check_code AS nvarchar(max)), N'', '')
        FROM app.fn_request_checks(@request_id, @actor) AS c
        WHERE c.check_status = N''FAIL'' AND c.check_code <> N''USER_ELIGIBLE_FOR_STAGE'';
        IF @failed IS NOT NULL
        BEGIN
            SET @msg = N''Approval is blocked by failed checks: '' + LEFT(@failed, 600) + N''.'';
            THROW 50144, @msg, 1;
        END
    END
    DECLARE @checks_json nvarchar(max) =
        (SELECT c.check_code AS code, c.check_status AS status
         FROM app.fn_request_checks(@request_id, @actor) AS c
         ORDER BY c.check_order
         FOR JSON PATH);

    /* ---- who a returned request goes to --------------------------------------------- */
    DECLARE @rtype nvarchar(10) = NULL, @rrec nvarchar(256) = NULL;
    IF @dec = N''RETURN''
    BEGIN
        IF @source = N''BUSINESS_RULE''
        BEGIN
            SET @rtype = N''GROUP'';
            SELECT @rrec = br.resolution_group FROM app.business_rules AS br WHERE br.rule_id = @rule AND br.rule_version = @rv;
            IF @rrec IS NULL SET @rrec = @rg;
        END
        ELSE IF LEFT(@by, 7) <> N''system:''
        BEGIN
            SET @rtype = N''USER'';
            SET @rrec = @by;
        END
        ELSE
        BEGIN
            SET @rtype = N''GROUP'';
            SET @rrec = @rg;
        END

        IF (@return_recipient IS NOT NULL OR @return_recipient_type IS NOT NULL)
           AND (UPPER(ISNULL(LTRIM(RTRIM(@return_recipient_type)), N'''')) <> @rtype
                OR LOWER(ISNULL(LTRIM(RTRIM(@return_recipient)), N'''')) <> LOWER(@rrec))
        BEGIN
            SET @msg = N''This request can only be returned to '' + @rrec + N'' ('' + @rtype + N'').'';
            THROW 50137, @msg, 1;
        END
    END

    /* ---- write ---------------------------------------------------------------------- */
    DECLARE @new_status nvarchar(24) = CASE WHEN @dec = N''REJECT'' THEN N''REJECTED''
                                            WHEN @dec = N''RETURN'' THEN N''RETURNED''
                                            WHEN @stage = N''RESPONSIBLE'' THEN N''PENDING_ACCOUNTABLE''
                                            ELSE N''APPROVED'' END;
    DECLARE @event_type nvarchar(24) = CASE WHEN @dec = N''REJECT'' THEN N''REJECTED''
                                            WHEN @dec = N''RETURN'' THEN N''RETURNED''
                                            WHEN @stage = N''RESPONSIBLE'' THEN N''RESPONSIBLE_APPROVED''
                                            ELSE N''ACCOUNTABLE_APPROVED'' END;
    DECLARE @details nvarchar(max) =
        (SELECT @stage AS stage, @dec AS decision, JSON_QUERY(@checks_json) AS checks,
                @rtype AS return_recipient_type, @rrec AS return_recipient
         FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
    DECLARE @req_mail nvarchar(256) = CASE WHEN @by = @actor THEN NULL ELSE @by END;
    DECLARE @ret_mail nvarchar(256) = CASE WHEN @rtype = N''USER'' THEN @rrec ELSE NULL END;
    DECLARE @ret_group nvarchar(64) = CASE WHEN @rtype = N''GROUP'' THEN @rrec ELSE NULL END;
    DECLARE @what nvarchar(400) = (SELECT TOP (1) ISNULL(fc.label, r.field_code) + N'' of '' + ISNULL(r.equipment_number, r.functional_location)
                                   FROM app.change_request AS r
                                   LEFT JOIN app.field_catalog AS fc ON fc.field_code = r.field_code
                                   WHERE r.request_id = @request_id);
    DECLARE @own bit = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;
    DECLARE @event_id bigint, @ek nvarchar(60), @t nvarchar(200), @b nvarchar(1000);

    BEGIN TRY
        IF @own = 1 BEGIN TRANSACTION;

        UPDATE app.change_request
        SET request_status = @new_status,
            updated_at_utc = SYSUTCDATETIME(),
            return_recipient_type = @rtype,
            return_recipient = @rrec
        WHERE request_id = @request_id AND request_status = @status AND row_version = @rowver;
        IF @@ROWCOUNT <> 1
            THROW 50149, N''Somebody else changed this request at the same moment: reload it and try again.'', 1;

        INSERT INTO app.change_request_event
            (request_id, event_type, approval_stage, actor, actor_group, comments, status_from, status_to, event_details_json)
        VALUES
            (@request_id, @event_type, @stage, @actor, @grp, @cmt, @status, @new_status, @details);
        SET @event_id = SCOPE_IDENTITY();
        SET @ek = N''E'' + CAST(@event_id AS nvarchar(20));

        IF @dec = N''APPROVE'' AND @stage = N''RESPONSIBLE''
        BEGIN
            SET @t = N''Request '' + @ref + N'' needs your approval'';
            SET @b = LEFT(@ref + N'': '' + @what + N'' passed the responsible stage and now waits for the accountable stage.'', 1000);
            EXEC app.usp_notification_enqueue @topic = N''REQUEST_PENDING_ACCOUNTABLE'', @request_id = @request_id, @event_key = @ek,
                                              @title = @t, @body = @b, @recipient_group = @ag;
        END
        ELSE IF @dec = N''APPROVE''
        BEGIN
            SET @t = N''Request '' + @ref + N'' was approved'';
            SET @b = LEFT(@ref + N'': '' + @what + N'' was approved by both stages.'', 1000);
            EXEC app.usp_notification_enqueue @topic = N''REQUEST_APPROVED'', @request_id = @request_id, @event_key = @ek,
                                              @title = @t, @body = @b, @recipient_email = @req_mail;
        END
        ELSE IF @dec = N''REJECT''
        BEGIN
            SET @t = N''Request '' + @ref + N'' was rejected'';
            SET @b = LEFT(@ref + N'': '' + @what + N'' was rejected. Comment: '' + @cmt, 1000);
            EXEC app.usp_notification_enqueue @topic = N''REQUEST_REJECTED'', @request_id = @request_id, @event_key = @ek,
                                              @title = @t, @body = @b, @recipient_email = @req_mail;
        END
        ELSE
        BEGIN
            SET @t = N''Request '' + @ref + N'' was returned to you'';
            SET @b = LEFT(@ref + N'': '' + @what + N'' was returned. Comment: '' + @cmt, 1000);
            EXEC app.usp_notification_enqueue @topic = N''REQUEST_RETURNED'', @request_id = @request_id, @event_key = @ek,
                                              @title = @t, @body = @b, @recipient_email = @ret_mail, @recipient_group = @ret_group;
        END

        IF @own = 1 COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @own = 1 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SET @o_new_status = @new_status;
    SET @o_needs_merge = CASE WHEN @new_status = N''APPROVED'' THEN 1 ELSE 0 END;

    IF @emit_result = 1
        SELECT @request_id AS request_id, @ref AS request_ref, @dec AS decision, @status AS previous_status,
               @new_status AS new_status, @stage AS stage, @o_needs_merge AS needs_merge;
END
');

PRINT N'--- db/procs/usp_request_bulk_decide.sql';
EXEC (N'/* =====================================================================
   app.usp_request_bulk_decide  APP-3; FINAL PLAN/03 APP-3 step 4 ("bulk approve")
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.usp_request_decide.

   Applies ONE decision to a list of requests, each on its own: every request gets its own
   transaction, its own event and its own notifications, and a request that cannot be decided is
   skipped with the reason (the refusal text of app.usp_request_decide) while the others go on.
   Nothing here is a business rule of its own: eligibility, checks and segregation are all in
   app.usp_request_decide, so a bulk approval can never do what a single approval refuses.

   Input : @request_ids, a comma-separated list of request numbers (at most 100; the same number twice
           counts once; processed in ascending order), @actor_email, @decision (APPROVE, REJECT or
           RETURN; the screen offers APPROVE), @comment (applied to every request; required for REJECT
           and RETURN).
   Output: one row per distinct number: request_id, request_ref, outcome (DECIDED or SKIPPED),
           new_status, needs_merge (1 = approved at the final stage, the function now calls the merge),
           reason (NULL when DECIDED).
   Refusal: 50151 an empty list, 50152 more than 100 requests.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_bulk_decide
    @request_ids nvarchar(4000),
    @actor_email nvarchar(256),
    @decision    nvarchar(10),
    @comment     nvarchar(1000) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ids TABLE (seq int IDENTITY(1,1) NOT NULL PRIMARY KEY, req_text nvarchar(40) NOT NULL);
    INSERT INTO @ids (req_text)
    SELECT x.req_text
    FROM (SELECT DISTINCT LTRIM(RTRIM(s.value)) AS req_text
          FROM STRING_SPLIT(ISNULL(@request_ids, N''''), N'','') AS s
          WHERE LTRIM(RTRIM(s.value)) <> N'''') AS x
    ORDER BY TRY_CONVERT(bigint, x.req_text), x.req_text;

    DECLARE @n int = (SELECT COUNT(*) FROM @ids);
    IF @n = 0
        THROW 50151, N''Name at least one request.'', 1;
    IF @n > 100
        THROW 50152, N''At most 100 requests can be decided at once.'', 1;

    DECLARE @res TABLE
    (
        seq int NOT NULL PRIMARY KEY, request_id bigint NULL, req_text nvarchar(40) NOT NULL,
        outcome nvarchar(10) NOT NULL, new_status nvarchar(24) NULL, needs_merge bit NOT NULL, reason nvarchar(400) NULL
    );

    DECLARE @i int = 1, @rid bigint, @txt nvarchar(40), @ns nvarchar(24), @nm bit;
    WHILE @i <= @n
    BEGIN
        SELECT @txt = d.req_text, @rid = TRY_CONVERT(bigint, d.req_text) FROM @ids AS d WHERE d.seq = @i;
        SET @ns = NULL;
        SET @nm = NULL;

        IF @rid IS NULL
            INSERT INTO @res (seq, request_id, req_text, outcome, new_status, needs_merge, reason)
            VALUES (@i, NULL, @txt, N''SKIPPED'', NULL, 0, N''not a request number'');
        ELSE
        BEGIN
            BEGIN TRY
                EXEC app.usp_request_decide @request_id = @rid, @actor_email = @actor_email, @decision = @decision,
                                            @comment = @comment, @emit_result = 0, @o_new_status = @ns OUTPUT, @o_needs_merge = @nm OUTPUT;
                INSERT INTO @res (seq, request_id, req_text, outcome, new_status, needs_merge, reason)
                VALUES (@i, @rid, @txt, N''DECIDED'', @ns, ISNULL(@nm, 0), NULL);
            END TRY
            BEGIN CATCH
                INSERT INTO @res (seq, request_id, req_text, outcome, new_status, needs_merge, reason)
                VALUES (@i, @rid, @txt, N''SKIPPED'', NULL, 0, LEFT(ERROR_MESSAGE(), 400));
            END CATCH;
        END
        SET @i += 1;
    END

    SELECT r.request_id, c.request_ref, r.outcome, r.new_status, r.needs_merge, r.reason
    FROM @res AS r
    LEFT JOIN app.change_request AS c ON c.request_id = r.request_id
    ORDER BY r.seq;
END
');

PRINT N'--- db/procs/usp_request_resubmit.sql';
EXEC (N'/* =====================================================================
   app.usp_request_resubmit     APP-3; FINAL PLAN/03 APP-3 step 5; workflow POC_Final/04, step 3 of the
                                return loop ("recipient corrects the proposed value ... and resubmits")
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.fn_value_check, app.usp_notification_enqueue.

   Sends a RETURNED request back to the first stage (PENDING_RESPONSIBLE), optionally with a corrected
   proposed value. Only the return recipient may do it: the submitter when the return went to a USER, an
   active member of the group when it went to a GROUP. A refusal is a THROW; nothing is written:

     50161 no such request                       50162 the request is not RETURNED
     50163 the person is not the return recipient (nor a member of the recipient group)
     50120 the corrected value equals the old value
     50121 the corrected value is not acceptable (app.fn_value_check)
     50164 another open request already proposes that change (same de-duplication key)
     50165 another open request proposes a different value for the same field
     50149 somebody else changed the request at the same moment

   With a corrected value the de-duplication key is computed again (same formula as
   app.usp_request_create: rule id, entity type, entity key, field, old value, new value). Both approval
   stages start again; an earlier approval stays in the history and still counts for the segregation rule.
   One transaction: status, value, key, return recipient cleared, RESUBMITTED event (comment, old and new
   proposed value), notification to the responsible group.

   Result: ONE row (request_id, request_ref, previous_status, new_status, new_value) when @emit_result = 1,
   and always @o_new_status.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_resubmit
    @request_id   bigint,
    @actor_email  nvarchar(256),
    @new_value    nvarchar(400)  = NULL,
    @comment      nvarchar(1000) = NULL,
    @emit_result  bit            = 1,
    @o_new_status nvarchar(24)   = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @msg nvarchar(2048);
    DECLARE @actor nvarchar(256) = LOWER(LTRIM(RTRIM(@actor_email)));
    DECLARE @cmt nvarchar(1000) = NULLIF(LTRIM(RTRIM(@comment)), N'''');
    DECLARE @nv nvarchar(400) = NULLIF(LTRIM(RTRIM(@new_value)), N'''');

    DECLARE @status nvarchar(24), @etype nvarchar(10), @eqid int, @eqnum nvarchar(18), @floc nvarchar(40), @field nvarchar(64);
    DECLARE @oldv nvarchar(400), @curv nvarchar(400), @rule nvarchar(64), @rg nvarchar(64), @rtype nvarchar(10), @rrec nvarchar(256);
    DECLARE @ref nvarchar(12), @rowver binary(8);
    SELECT @status = r.request_status, @etype = r.entity_type, @eqid = r.equipment_id, @eqnum = r.equipment_number,
           @floc = r.functional_location, @field = r.field_code, @oldv = r.old_value, @curv = r.new_value,
           @rule = r.source_rule_id, @rg = r.responsible_group, @rtype = r.return_recipient_type, @rrec = r.return_recipient,
           @ref = r.request_ref, @rowver = r.row_version
    FROM app.change_request AS r
    WHERE r.request_id = @request_id;
    IF @status IS NULL
        THROW 50161, N''That request does not exist.'', 1;
    IF @status <> N''RETURNED''
    BEGIN
        SET @msg = N''The request is '' + @status + N''; only a returned request can be resubmitted.'';
        THROW 50162, @msg, 1;
    END

    IF NOT (   (@rtype = N''USER'' AND LOWER(@rrec) = @actor)
            OR (@rtype = N''GROUP'' AND EXISTS (SELECT 1 FROM app.group_membership AS m
                                              WHERE m.group_key = @rrec AND m.is_active = 1 AND m.user_email = @actor)))
        THROW 50163, N''Only the person or group the request was returned to may resubmit it.'', 1;

    /* ---- a corrected value ----------------------------------------------------------- */
    DECLARE @newv nvarchar(400) = @curv;
    DECLARE @key char(64) = NULL;
    IF @nv IS NOT NULL AND @nv COLLATE Latin1_General_BIN2 <> ISNULL(@curv, N'''') COLLATE Latin1_General_BIN2
    BEGIN
        DECLARE @ftype nvarchar(10) = (SELECT c.data_type FROM app.field_catalog AS c WHERE c.field_code = @field);
        DECLARE @problem nvarchar(400) = (SELECT v.problem FROM app.fn_value_check(@field, @nv) AS v);
        IF @problem IS NOT NULL
        BEGIN
            SET @msg = N''The corrected value is not acceptable: '' + @problem + N''.'';
            THROW 50121, @msg, 1;
        END
        DECLARE @same bit = 0;
        IF @ftype = N''DECIMAL'' AND TRY_CONVERT(decimal(18,4), @nv) IS NOT NULL AND TRY_CONVERT(decimal(18,4), @oldv) IS NOT NULL
            SET @same = CASE WHEN TRY_CONVERT(decimal(18,4), @nv) = TRY_CONVERT(decimal(18,4), @oldv) THEN 1 ELSE 0 END;
        ELSE
            SET @same = CASE WHEN ISNULL(@oldv, N'''') COLLATE Latin1_General_BIN2 = @nv COLLATE Latin1_General_BIN2 THEN 1 ELSE 0 END;
        IF @same = 1
            THROW 50120, N''The corrected value is the same as the old value.'', 1;

        DECLARE @entity_key nvarchar(40) = CASE WHEN @etype = N''EQUIPMENT'' THEN @eqnum ELSE @floc END;
        SET @key = CONVERT(char(64), HASHBYTES(''SHA2_256'',
            CONCAT(ISNULL(@rule, N''''), NCHAR(31), @etype, NCHAR(31), @entity_key, NCHAR(31),
                   @field, NCHAR(31), ISNULL(@oldv, N''''), NCHAR(31), @nv)), 2);

        IF EXISTS (SELECT 1 FROM app.change_request AS d
                   WHERE d.deduplication_key = @key AND d.request_id <> @request_id
                     AND d.request_status <> N''APPROVED'' AND d.request_status <> N''REJECTED'' AND d.request_status <> N''CANCELLED'')
            THROW 50164, N''Another open request already proposes that change.'', 1;
        IF EXISTS (SELECT 1 FROM app.change_request AS o
                   WHERE o.request_id <> @request_id AND o.field_code = @field
                     AND o.request_status <> N''APPROVED'' AND o.request_status <> N''REJECTED'' AND o.request_status <> N''CANCELLED''
                     AND (   (@etype = N''EQUIPMENT'' AND o.equipment_id = @eqid)
                          OR (@etype = N''FLOC'' AND o.entity_type = N''FLOC'' AND o.functional_location = @floc))
                     AND ISNULL(o.new_value, N'''') COLLATE Latin1_General_BIN2 <> @nv COLLATE Latin1_General_BIN2)
            THROW 50165, N''Another open request proposes a different value for the same field.'', 1;
        SET @newv = @nv;
    END

    /* ---- write ----------------------------------------------------------------------- */
    DECLARE @details nvarchar(max) =
        (SELECT @curv AS previous_new_value, @newv AS new_value FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
    DECLARE @what nvarchar(400) = (SELECT TOP (1) ISNULL(fc.label, r.field_code) + N'' of '' + ISNULL(r.equipment_number, r.functional_location)
                                   FROM app.change_request AS r
                                   LEFT JOIN app.field_catalog AS fc ON fc.field_code = r.field_code
                                   WHERE r.request_id = @request_id);
    DECLARE @own bit = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;
    DECLARE @event_id bigint, @ek nvarchar(60), @t nvarchar(200), @b nvarchar(1000);

    BEGIN TRY
        IF @own = 1 BEGIN TRANSACTION;

        UPDATE app.change_request
        SET request_status = N''PENDING_RESPONSIBLE'',
            new_value = @newv,
            deduplication_key = ISNULL(@key, deduplication_key),
            return_recipient_type = NULL,
            return_recipient = NULL,
            updated_at_utc = SYSUTCDATETIME()
        WHERE request_id = @request_id AND request_status = N''RETURNED'' AND row_version = @rowver;
        IF @@ROWCOUNT <> 1
            THROW 50149, N''Somebody else changed this request at the same moment: reload it and try again.'', 1;

        INSERT INTO app.change_request_event
            (request_id, event_type, approval_stage, actor, actor_group, comments, status_from, status_to, event_details_json)
        VALUES
            (@request_id, N''RESUBMITTED'', NULL, @actor, NULL, @cmt, N''RETURNED'', N''PENDING_RESPONSIBLE'', @details);
        SET @event_id = SCOPE_IDENTITY();
        SET @ek = N''E'' + CAST(@event_id AS nvarchar(20));

        SET @t = N''Request '' + @ref + N'' needs your approval again'';
        SET @b = LEFT(@ref + N'': '' + @what + N'' was resubmitted with the proposed value "'' + @newv + N''".'', 1000);
        EXEC app.usp_notification_enqueue @topic = N''REQUEST_PENDING_RESPONSIBLE'', @request_id = @request_id, @event_key = @ek,
                                          @title = @t, @body = @b, @recipient_group = @rg;

        IF @own = 1 COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @own = 1 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SET @o_new_status = N''PENDING_RESPONSIBLE'';
    IF @emit_result = 1
        SELECT @request_id AS request_id, @ref AS request_ref, N''RETURNED'' AS previous_status,
               N''PENDING_RESPONSIBLE'' AS new_status, @newv AS new_value;
END
');

PRINT N'--- db/procs/usp_request_cancel.sql';
EXEC (N'/* =====================================================================
   app.usp_request_cancel       APP-3; FINAL PLAN/03 APP-3 step 5 ("requester withdraws")
   Single statement per file; CREATE OR ALTER, safe to run again.

   Withdraws an open request (PENDING_RESPONSIBLE, PENDING_ACCOUNTABLE, RETURNED or DRAFT): status
   CANCELLED, one CANCELLED event. The row stays (nothing is ever deleted). Closing it frees its
   de-duplication key, so the same change can be raised again by a person; a RULE source stays
   suppressed after a cancellation (app.usp_request_create, REF-52 [L0187]).

   Who may: the person who raised it (requested_by); and, while it is RETURNED, the person or group
   member it was returned to ("the recipient ... withdraws (CANCELLED)", POC_Final/04). A refusal is a
   THROW; nothing is written:
     50171 no such request        50172 the request is already closed (APPROVED, REJECTED or CANCELLED)
     50173 not the requester and not the return recipient
     50149 somebody else changed the request at the same moment
   No notification is queued (the notification topics of 09 section 7.1 have none for a withdrawal).

   Result: ONE row (request_id, request_ref, previous_status, new_status) when @emit_result = 1,
   and always @o_new_status.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_cancel
    @request_id   bigint,
    @actor_email  nvarchar(256),
    @comment      nvarchar(1000) = NULL,
    @emit_result  bit            = 1,
    @o_new_status nvarchar(24)   = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @msg nvarchar(2048);
    DECLARE @actor nvarchar(256) = LOWER(LTRIM(RTRIM(@actor_email)));
    DECLARE @cmt nvarchar(1000) = NULLIF(LTRIM(RTRIM(@comment)), N'''');

    DECLARE @status nvarchar(24), @by nvarchar(256), @rtype nvarchar(10), @rrec nvarchar(256), @ref nvarchar(12), @rowver binary(8);
    SELECT @status = r.request_status, @by = r.requested_by, @rtype = r.return_recipient_type, @rrec = r.return_recipient,
           @ref = r.request_ref, @rowver = r.row_version
    FROM app.change_request AS r
    WHERE r.request_id = @request_id;
    IF @status IS NULL
        THROW 50171, N''That request does not exist.'', 1;
    IF @status IN (N''APPROVED'', N''REJECTED'', N''CANCELLED'')
    BEGIN
        SET @msg = N''The request is already '' + @status + N''; it cannot be withdrawn.'';
        THROW 50172, @msg, 1;
    END

    IF @actor IS NULL OR @actor = N'''' OR LEFT(@actor, 7) = N''system:''
       OR NOT (   LOWER(@by) = @actor
               OR (@status = N''RETURNED'' AND @rtype = N''USER'' AND LOWER(@rrec) = @actor)
               OR (@status = N''RETURNED'' AND @rtype = N''GROUP''
                   AND EXISTS (SELECT 1 FROM app.group_membership AS m
                               WHERE m.group_key = @rrec AND m.is_active = 1 AND m.user_email = @actor)))
        THROW 50173, N''Only the person who raised the request, or the person it was returned to, may withdraw it.'', 1;

    DECLARE @own bit = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;
    BEGIN TRY
        IF @own = 1 BEGIN TRANSACTION;

        UPDATE app.change_request
        SET request_status = N''CANCELLED'',
            updated_at_utc = SYSUTCDATETIME()
        WHERE request_id = @request_id AND request_status = @status AND row_version = @rowver;
        IF @@ROWCOUNT <> 1
            THROW 50149, N''Somebody else changed this request at the same moment: reload it and try again.'', 1;

        INSERT INTO app.change_request_event
            (request_id, event_type, approval_stage, actor, actor_group, comments, status_from, status_to, event_details_json)
        VALUES
            (@request_id, N''CANCELLED'', NULL, @actor, NULL, @cmt, @status, N''CANCELLED'', NULL);

        IF @own = 1 COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @own = 1 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SET @o_new_status = N''CANCELLED'';
    IF @emit_result = 1
        SELECT @request_id AS request_id, @ref AS request_ref, @status AS previous_status, N''CANCELLED'' AS new_status;
END
');

PRINT N'--- db/procs/usp_request_record_merge.sql';
EXEC (N'/* =====================================================================
   app.usp_request_record_merge  APP-3; FINAL PLAN/01 section 6.5 (merge contract) and 2.2
   Single statement per file; CREATE OR ALTER, safe to run again.

   Records what the merge into gold answered for an APPROVED request. The caller is a function (right
   after the final approval) or the data engineer''s re-apply notebook (NB-3); the approval itself is never
   rolled back because a merge failed or found a stale value (01 section 2.2, POC-DE-20).

   Input : @request_id; @outcome as returned by gold.usp_apply_approved_change: APPLIED, STALE,
           ALREADY_APPLIED, NOT_ELIGIBLE or ERROR; its message and golden_version_id; @actor (default
           system:merge).
   Event written (the request status does not change, status_from and status_to stay empty):
     APPLIED, ALREADY_APPLIED  ->  MERGED        (details: outcome, message, golden_version_id)
     STALE                     ->  MERGE_STALE   (the golden value moved on since the request was raised)
     NOT_ELIGIBLE, ERROR       ->  COMMENTED     ("Merge ERROR: <message>"), so the approver sees that the
                                   merge did not happen and why; the request stays APPROVED without a MERGED
                                   event, so the merge can be tried again later
   A request that already has a MERGED event gets no second event: the call answers ALREADY_RECORDED
   (the merge is applied once). Each STALE / ERROR attempt is recorded: it is history.

   Refusals: 50181 no such request, 50182 the request is not APPROVED, 50183 unknown outcome.
   Result: ONE row (request_id, request_ref, recorded) with recorded = MERGED, MERGE_STALE, COMMENTED or
   ALREADY_RECORDED.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_record_merge
    @request_id        bigint,
    @outcome           nvarchar(16),
    @message           nvarchar(400) = NULL,
    @golden_version_id int           = NULL,
    @actor             nvarchar(256) = N''system:merge''
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @out nvarchar(16) = UPPER(LTRIM(RTRIM(@outcome)));
    DECLARE @who nvarchar(256) = LOWER(LTRIM(RTRIM(ISNULL(@actor, N''system:merge''))));
    DECLARE @msg nvarchar(400) = NULLIF(LTRIM(RTRIM(@message)), N'''');

    DECLARE @status nvarchar(24), @ref nvarchar(12);
    SELECT @status = r.request_status, @ref = r.request_ref
    FROM app.change_request AS r
    WHERE r.request_id = @request_id;
    IF @status IS NULL
        THROW 50181, N''That request does not exist.'', 1;
    IF @status <> N''APPROVED''
        THROW 50182, N''Only an approved request has a merge to record.'', 1;
    IF @out IS NULL OR @out NOT IN (N''APPLIED'', N''STALE'', N''ALREADY_APPLIED'', N''NOT_ELIGIBLE'', N''ERROR'')
        THROW 50183, N''Unknown merge outcome.'', 1;

    DECLARE @recorded nvarchar(16);
    IF EXISTS (SELECT 1 FROM app.change_request_event AS e WHERE e.request_id = @request_id AND e.event_type = N''MERGED'')
        SET @recorded = N''ALREADY_RECORDED'';
    ELSE
    BEGIN
        DECLARE @type nvarchar(24) = CASE WHEN @out IN (N''APPLIED'', N''ALREADY_APPLIED'') THEN N''MERGED''
                                          WHEN @out = N''STALE'' THEN N''MERGE_STALE''
                                          ELSE N''COMMENTED'' END;
        DECLARE @comments nvarchar(1000) = CASE WHEN @type = N''COMMENTED'' THEN LEFT(N''Merge '' + @out + N'': '' + ISNULL(@msg, N''(no message)''), 1000) ELSE @msg END;
        DECLARE @details nvarchar(max) = (SELECT @out AS outcome, @msg AS message, @golden_version_id AS golden_version_id
                                          FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
        INSERT INTO app.change_request_event
            (request_id, event_type, approval_stage, actor, actor_group, comments, status_from, status_to, event_details_json)
        VALUES
            (@request_id, @type, NULL, @who, NULL, @comments, NULL, NULL, @details);
        SET @recorded = @type;
    END

    SELECT @request_id AS request_id, @ref AS request_ref, @recorded AS recorded;
END
');

PRINT N'--- db/procs/usp_request_mark_exported.sql';
EXEC (N'/* =====================================================================
   app.usp_request_mark_exported  APP-3; FINAL PLAN/01 section 6.6 (export contract; the data engineer calls it)
   Single statement per file; CREATE OR ALTER, safe to run again.

   The data engineer''s export notebook (NB-5) calls this once for each request whose change it wrote into an
   EVOLVE template row:
     EXEC app.usp_request_mark_exported @request_id = 42, @batch_id = 7, @template_code = N''EQUIPMENT_UPDATE'', @row_number = 15;
   It adds one EXPORTED event (details: batch, template, row). Nothing else changes: the request stays APPROVED.

   Eligible: the request is APPROVED and has a MERGED event (the change is in the golden record), and has no
   EXPORTED event yet. A second call for the same request answers ALREADY_RECORDED and adds nothing, so a
   notebook that re-runs does not duplicate the history.
   Refusals: 50191 no such request, 50192 not APPROVED or not merged yet, 50193 no template code or row number.
   Result: ONE row (request_id, request_ref, recorded) with recorded = EXPORTED or ALREADY_RECORDED.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_mark_exported
    @request_id    bigint,
    @batch_id      bigint,
    @template_code nvarchar(40),
    @row_number    int,
    @actor         nvarchar(256) = N''system:de''
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @tpl nvarchar(40) = NULLIF(LTRIM(RTRIM(@template_code)), N'''');
    DECLARE @who nvarchar(256) = LOWER(LTRIM(RTRIM(ISNULL(@actor, N''system:de''))));

    DECLARE @status nvarchar(24), @ref nvarchar(12);
    SELECT @status = r.request_status, @ref = r.request_ref
    FROM app.change_request AS r
    WHERE r.request_id = @request_id;
    IF @status IS NULL
        THROW 50191, N''That request does not exist.'', 1;
    IF @tpl IS NULL OR @batch_id IS NULL OR @row_number IS NULL
        THROW 50193, N''A batch, a template code and a row number are required.'', 1;
    IF @status <> N''APPROVED''
       OR NOT EXISTS (SELECT 1 FROM app.change_request_event AS e WHERE e.request_id = @request_id AND e.event_type = N''MERGED'')
        THROW 50192, N''Only an approved request whose change has been merged can be marked as exported.'', 1;

    DECLARE @recorded nvarchar(16);
    IF EXISTS (SELECT 1 FROM app.change_request_event AS e WHERE e.request_id = @request_id AND e.event_type = N''EXPORTED'')
        SET @recorded = N''ALREADY_RECORDED'';
    ELSE
    BEGIN
        DECLARE @details nvarchar(max) = (SELECT @batch_id AS batch_id, @tpl AS template_code, @row_number AS [row_number]
                                          FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
        INSERT INTO app.change_request_event
            (request_id, event_type, approval_stage, actor, actor_group, comments, status_from, status_to, event_details_json)
        VALUES
            (@request_id, N''EXPORTED'', NULL, @who, NULL, NULL, NULL, NULL, @details);
        SET @recorded = N''EXPORTED'';
    END

    SELECT @request_id AS request_id, @ref AS request_ref, @recorded AS recorded;
END
');

PRINT N'--- db/procs/usp_request_evidence.sql';
EXEC (N'/* =====================================================================
   app.usp_request_evidence     APP-3; FINAL PLAN/03 section 2.2 (function getRequestEvidence)
   Single statement per file; CREATE OR ALTER, safe to run again. Reads only.

   The evidence snapshot of one request: what the requester (or the rule) had in front of them when the
   request was created. It is stored on the CREATED event (event_details_json, nvarchar(max), so it is read
   through a function and never through the connector or a view, 09 section 4.2):

     { "event": "CREATED", "source_type": ..., "entity_type": ..., "entity_key": ..., "route_used": ...,
       "golden_version_id": ..., "baseline_as_of_utc": ..., "evidence": { ...whatever the caller supplied... } }

   Input : @request_id.
   Output: ONE row: request_id, request_ref, created_at_utc, created_by, details_json (the text above).
   Refusal: 50201 when the request does not exist (or has no CREATED event, which no request created by
   app.usp_request_create can lack).
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_evidence
    @request_id bigint
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM app.change_request AS r WHERE r.request_id = @request_id)
        THROW 50201, N''That request does not exist.'', 1;

    SELECT TOP (1)
        r.request_id,
        r.request_ref,
        e.occurred_at_utc    AS created_at_utc,
        e.actor              AS created_by,
        e.event_details_json AS details_json
    FROM app.change_request AS r
    JOIN app.change_request_event AS e ON e.request_id = r.request_id AND e.event_type = N''CREATED''
    WHERE r.request_id = @request_id
    ORDER BY e.event_id;
END
');

PRINT N'--- db/views/vw_request_queue.sql';
EXEC (N'/* =====================================================================
   app.vw_request_queue         APP-3; FINAL PLAN/09 section 9; screens S-1 (home counts), S-2 (approvals)
   Single statement per file; CREATE OR ALTER, safe to run again.
   Read through a read function and procedure (D-17; they are built with the screens in APP-4: the
   queue procedure takes the caller''s e-mail because "my queue" depends on who is asking).

   One row per change request, with everything a queue row shows. No nvarchar(max) column. Key: request_id.

     approval_stage     RESPONSIBLE or ACCOUNTABLE while the request waits for a decision, NULL otherwise
     field_label        the catalogue label (NULL for a request without a field)
     sap_field          the catalogue''s sap_column (NULL until the data engineer fills the mapping, DE-3)
     source_label       "Rule <id> v<version>" for a rule request; "Field submission", "Manual request",
                        "Correction import", "New field request", "New heater request" otherwise
     detected_at_utc    when the rule found it (the start of the cycle-time clock); NULL for a person''s request
     age_hours          whole hours since requested while the request is open; NULL once it is closed
     photo_count        active files of type PHOTO linked to the request in app.file_index
     equipment_tag_number  the heater''s tag now (gold.vw_equipment_current); NULL for a FLOC request
   ===================================================================== */
CREATE OR ALTER VIEW app.vw_request_queue
AS
SELECT
    r.request_id,
    r.request_ref,
    r.request_status,
    CAST(CASE r.request_status WHEN N''PENDING_RESPONSIBLE'' THEN N''RESPONSIBLE''
                               WHEN N''PENDING_ACCOUNTABLE'' THEN N''ACCOUNTABLE''
                               ELSE NULL END AS nvarchar(12))                         AS approval_stage,
    r.entity_type,
    r.equipment_id,
    r.equipment_number,
    r.functional_location,
    e.equipment_tag_number,
    r.profit_center_name,
    r.field_code,
    fc.label                                                                          AS field_label,
    fc.sap_column                                                                     AS sap_field,
    r.old_value,
    r.new_value,
    r.reason,
    r.note,
    r.source_type,
    r.source_rule_id,
    r.source_rule_version,
    CAST(CASE r.source_type
             WHEN N''BUSINESS_RULE''      THEN N''Rule '' + ISNULL(r.source_rule_id, N''?'') + N'' v'' + ISNULL(CAST(r.source_rule_version AS nvarchar(10)), N''?'')
             WHEN N''FIELD''              THEN N''Field submission''
             WHEN N''MANUAL''             THEN N''Manual request''
             WHEN N''CORRECTION_IMPORT''  THEN N''Correction import''
             WHEN N''NEW_CHARACTERISTIC'' THEN N''New field request''
             WHEN N''NEW_RECORD''         THEN N''New heater request''
             ELSE r.source_type END AS nvarchar(120))                                 AS source_label,
    r.requested_by,
    r.requested_at_utc,
    rs.detected_at_utc,
    r.responsible_group,
    r.accountable_group,
    r.return_recipient_type,
    r.return_recipient,
    CAST(CASE WHEN r.request_status = N''APPROVED'' OR r.request_status = N''REJECTED'' OR r.request_status = N''CANCELLED''
              THEN NULL
              ELSE DATEDIFF(hour, r.requested_at_utc, SYSUTCDATETIME()) END AS int)   AS age_hours,
    CAST(ISNULL(ph.n, 0) AS int)                                                      AS photo_count,
    r.updated_at_utc
FROM app.change_request AS r
LEFT JOIN app.field_catalog AS fc ON fc.field_code = r.field_code
LEFT JOIN gold.vw_equipment_current AS e ON e.equipment_id = r.equipment_id
LEFT JOIN app.business_rule_result AS rs ON rs.result_id = r.source_result_id
OUTER APPLY
(
    SELECT COUNT(*) AS n
    FROM app.file_index AS f
    WHERE f.request_id = r.request_id AND f.file_type = N''PHOTO'' AND f.is_active = 1
) AS ph;
');

PRINT N'--- db/views/vw_request_event.sql';
EXEC (N'/* =====================================================================
   app.vw_request_event         APP-3; FINAL PLAN/09 section 9; screens S-3 (Audit and routing tab), S-5 (history)
   Single statement per file; CREATE OR ALTER, safe to run again.
   Read through a read function and procedure (D-17; built with the screens in APP-4).

   One row per event of app.change_request_event, oldest first by occurred_at_utc and event_id. The long
   JSON column (event_details_json) is left out on purpose: it is nvarchar(max) and is read through a
   function when a screen needs the check results or the evidence snapshot (getRequestEvidence).
   Key: event_id.
   ===================================================================== */
CREATE OR ALTER VIEW app.vw_request_event
AS
SELECT
    ev.event_id,
    ev.request_id,
    ev.event_type,
    ev.approval_stage,
    ev.actor,
    ev.actor_group,
    ev.occurred_at_utc,
    ev.comments,
    ev.status_from,
    ev.status_to
FROM app.change_request_event AS ev;
');

PRINT N'--- db/views/vw_equipment_request.sql';
EXEC (N'/* =====================================================================
   app.vw_equipment_request     APP-3; FINAL PLAN/09 section 9; screens S-3 (related requests), S-5 (related requests)
   Single statement per file; CREATE OR ALTER, safe to run again.
   Read through a read function and procedure (D-17; built with the screens in APP-4).

   Requests by heater and by functional location (FLOC), one row per request, with an overlap flag:

     equipment_id            the heater (NULL for a FLOC request)
     functional_location     the FLOC the request is about (a FLOC request) or the heater''s FLOC at creation
     is_open                 1 while the status is not APPROVED, REJECTED or CANCELLED
     other_open_requests_same_field  how many OTHER open requests target the same field of the same heater
                             (or of the same FLOC); 0 for a closed request. More than 0 is the overlap flag
                             S-3 and S-5 show.
   Screens ask for the rows of one heater: its own requests (equipment_id), plus the FLOC requests at its
   functional_location. Key: request_id.
   ===================================================================== */
CREATE OR ALTER VIEW app.vw_equipment_request
AS
SELECT
    r.request_id,
    r.equipment_id,
    r.functional_location,
    r.field_code,
    fc.label                                                                       AS field_label,
    r.request_ref,
    r.request_status,
    CAST(CASE WHEN r.request_status = N''APPROVED'' OR r.request_status = N''REJECTED'' OR r.request_status = N''CANCELLED''
              THEN 0 ELSE 1 END AS bit)                                            AS is_open,
    CAST(CASE r.source_type
             WHEN N''BUSINESS_RULE''      THEN N''Rule '' + ISNULL(r.source_rule_id, N''?'') + N'' v'' + ISNULL(CAST(r.source_rule_version AS nvarchar(10)), N''?'')
             WHEN N''FIELD''              THEN N''Field submission''
             WHEN N''MANUAL''             THEN N''Manual request''
             WHEN N''CORRECTION_IMPORT''  THEN N''Correction import''
             WHEN N''NEW_CHARACTERISTIC'' THEN N''New field request''
             WHEN N''NEW_RECORD''         THEN N''New heater request''
             ELSE r.source_type END AS nvarchar(120))                              AS source_label,
    r.requested_at_utc,
    CAST(CASE WHEN r.request_status = N''APPROVED'' OR r.request_status = N''REJECTED'' OR r.request_status = N''CANCELLED''
              THEN 0 ELSE ISNULL(ov.n, 0) END AS int)                              AS other_open_requests_same_field
FROM app.change_request AS r
LEFT JOIN app.field_catalog AS fc ON fc.field_code = r.field_code
OUTER APPLY
(
    SELECT COUNT(*) AS n
    FROM app.change_request AS o
    WHERE o.request_id <> r.request_id
      AND o.field_code = r.field_code
      AND o.request_status <> N''APPROVED'' AND o.request_status <> N''REJECTED'' AND o.request_status <> N''CANCELLED''
      AND (   (r.entity_type = N''EQUIPMENT'' AND o.equipment_id = r.equipment_id)
           OR (r.entity_type = N''FLOC'' AND o.entity_type = N''FLOC'' AND o.functional_location = r.functional_location))
) AS ov;
');

PRINT N'--- db/views/vw_request_detail.sql';
EXEC (N'/* =====================================================================
   app.vw_request_detail        APP-3; FINAL PLAN/09 section 9; screen S-3 (request detail)
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs app.vw_request_queue (create it first). Read through a read function and procedure
   (D-17; built with the screens in APP-4).

   One row per request: every column of app.vw_request_queue (q.*, the same names, types and order) plus what
   the detail screen adds from the request and its events. Key: request_id. No nvarchar(max) column.

     class_code, route_id     as stored on the request
     creation_comment         the comment of the CREATED event
     last_decision_by / _at   actor and time of the latest decision event (RESPONSIBLE_APPROVED,
                              ACCOUNTABLE_APPROVED, REJECTED or RETURNED); NULL while none
     merge_outcome            APPLIED, STALE, ALREADY_APPLIED, NOT_ELIGIBLE or ERROR, from the latest merge
                              event (MERGED, MERGE_STALE) or merge-failure COMMENTED event; NULL before a merge
                              was tried
     merged_at_utc            time of the MERGED event (NULL until applied)
     golden_version_id        the golden version the merge produced (from the merge event); NULL otherwise
     exported_at_utc, evolve_batch_id, evolve_row_number   from the EXPORTED event; NULL until exported

   The merge and export facts come out of event_details_json with JSON_VALUE (the column itself stays inside
   the database, it is nvarchar(max)).
   ===================================================================== */
CREATE OR ALTER VIEW app.vw_request_detail
AS
SELECT
    q.*,
    r.class_code,
    r.route_id,
    cr.comments                                                    AS creation_comment,
    dc.actor                                                       AS last_decision_by,
    dc.occurred_at_utc                                             AS last_decision_at_utc,
    CAST(JSON_VALUE(mg.event_details_json, ''$.outcome'') AS nvarchar(16))               AS merge_outcome,
    mdone.occurred_at_utc                                          AS merged_at_utc,
    TRY_CONVERT(int, JSON_VALUE(mg.event_details_json, ''$.golden_version_id''))         AS golden_version_id,
    ex.occurred_at_utc                                             AS exported_at_utc,
    TRY_CONVERT(bigint, JSON_VALUE(ex.event_details_json, ''$.batch_id''))               AS evolve_batch_id,
    TRY_CONVERT(int, JSON_VALUE(ex.event_details_json, ''$.row_number''))                AS evolve_row_number
FROM app.vw_request_queue AS q
JOIN app.change_request AS r ON r.request_id = q.request_id
OUTER APPLY (SELECT TOP (1) e.comments
             FROM app.change_request_event AS e
             WHERE e.request_id = r.request_id AND e.event_type = N''CREATED''
             ORDER BY e.event_id) AS cr
OUTER APPLY (SELECT TOP (1) e.actor, e.occurred_at_utc
             FROM app.change_request_event AS e
             WHERE e.request_id = r.request_id
               AND e.event_type IN (N''RESPONSIBLE_APPROVED'', N''ACCOUNTABLE_APPROVED'', N''REJECTED'', N''RETURNED'')
             ORDER BY e.event_id DESC) AS dc
OUTER APPLY (SELECT TOP (1) e.event_details_json
             FROM app.change_request_event AS e
             WHERE e.request_id = r.request_id
               AND (e.event_type IN (N''MERGED'', N''MERGE_STALE'')
                    OR (e.event_type = N''COMMENTED'' AND e.actor LIKE N''system:%'' AND JSON_VALUE(e.event_details_json, ''$.outcome'') IS NOT NULL))
             ORDER BY e.event_id DESC) AS mg
OUTER APPLY (SELECT TOP (1) e.occurred_at_utc
             FROM app.change_request_event AS e
             WHERE e.request_id = r.request_id AND e.event_type = N''MERGED''
             ORDER BY e.event_id DESC) AS mdone
OUTER APPLY (SELECT TOP (1) e.occurred_at_utc, e.event_details_json
             FROM app.change_request_event AS e
             WHERE e.request_id = r.request_id AND e.event_type = N''EXPORTED''
             ORDER BY e.event_id DESC) AS ex;
');

PRINT N'=== end of app3_1_request_objects ===';
